// Copies the vendored design system (design-system/) into src/styles/ds/ for the app to import.
// - tokens.css is copied as-is.
// - components/bundle.css has its Google Fonts @import removed: fonts are self-hosted
//   via @fontsource (see src/main.jsx), so no third-party font requests are made.
// Also writes the booking plugin's admin tokens: the light theme only, scoped to `.ishot-admin`
// so the design system's generic names (--ink, --line, ...) never leak into the rest of wp-admin.
// Runs automatically before `npm run dev` and `npm run build`. Never edit the generated files by hand.
import { copyFileSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const outDir = resolve(root, "src/styles/ds");
mkdirSync(outDir, { recursive: true });

const banner = "/* GENERATED by scripts/sync-design-system.mjs from design-system/. Do not edit. */\n";

const tokens = readFileSync(resolve(root, "design-system/tokens.css"), "utf8");
const bundleSrc = readFileSync(resolve(root, "design-system/components/bundle.css"), "utf8");
const bundle = bundleSrc.replace(/^@import url\([^)]*fonts\.googleapis\.com[^)]*\);[ \t]*\r?\n?/m, "");

if (bundle === bundleSrc) {
  console.warn("sync-design-system: no Google Fonts @import found in bundle.css; check the vendored file.");
}

writeFileSync(resolve(outDir, "tokens.css"), banner + tokens);
writeFileSync(resolve(outDir, "bundle.css"), banner + bundle);
// Custom-property blocks only (light theme + shared scales). The type classes are left out on purpose:
// the design system's `.button` etc. would restyle wp-admin's own controls.
const rootBlocks = [...tokens.matchAll(/^:root(?:,\s*\[data-theme="light"\])?\s*\{[^}]*\}/gm)].map((m) => m[0]);
if (rootBlocks.length !== 2) throw new Error(`sync-design-system: expected 2 :root blocks in tokens.css, found ${rootBlocks.length}`);
const scoped = rootBlocks.map((block) => block.replace(/^:root[^{]*\{/, ".ishot-admin {")).join("\n");
const pluginCss = resolve(root, "wordpress/wp-content/plugins/ishot-booking/assets/css");
mkdirSync(pluginCss, { recursive: true });
writeFileSync(resolve(pluginCss, "tokens.css"), banner + scoped + "\n");

// Email palette: email clients ignore CSS custom properties, so the booking emails inline these
// resolved light-theme values (aliases such as `{brand-navy}` are followed to their hex).
const json = JSON.parse(readFileSync(resolve(root, "design-system/tokens.json"), "utf8"));
const light = Object.fromEntries(json.color.tokens.map((t) => [t.name, t.value.light]));
const resolveColour = (v, seen = 0) => {
  const alias = /^\{([\w-]+)\}$/.exec(v);
  if (!alias) return v;
  if (seen > 5 || !(alias[1] in light)) throw new Error(`sync-design-system: unresolvable colour alias ${v}`);
  return resolveColour(light[alias[1]], seen + 1);
};
const emailKeys = ["paper", "mist", "ink", "ink-muted", "line", "band", "on-band", "on-band-muted", "accent", "on-accent", "highlight"];
const email = {
  _generated: "scripts/sync-design-system.mjs from design-system/tokens.json. Do not edit.",
  colour: Object.fromEntries(emailKeys.map((k) => [k, resolveColour(light[k])])),
  font: { display: json.type.families.display, text: json.type.families.text },
};
const pluginEmail = resolve(root, "wordpress/wp-content/plugins/ishot-booking/assets/email");
mkdirSync(pluginEmail, { recursive: true });
writeFileSync(resolve(pluginEmail, "theme.json"), JSON.stringify(email, null, 2) + "\n");
// ---------------------------------------------------------------------------------------------
// WordPress theme (wordpress/wp-content/themes/ishot-concept):
// - assets/css/tokens.css + bundle.css: identical to the app's, so `fo-` markup renders the same.
// - assets/fonts/: self-hosted latin woff2 subsets copied from @fontsource.
// - theme.json: theme.base.json (hand-kept) + presets generated from tokens.json.
const theme = resolve(root, "wordpress/wp-content/themes/ishot-concept");
mkdirSync(resolve(theme, "assets/css"), { recursive: true });
writeFileSync(resolve(theme, "assets/css/tokens.css"), banner + tokens);
writeFileSync(resolve(theme, "assets/css/bundle.css"), banner + bundle);

const FONTS = { display: { pkg: "oswald", family: "Oswald", weights: [500, 600, 700] }, text: { pkg: "space-grotesk", family: "Space Grotesk", weights: [400, 500, 700] } };
mkdirSync(resolve(theme, "assets/fonts"), { recursive: true });
const latinRange = (pkg, weight) => {
  const css = readFileSync(resolve(root, `node_modules/@fontsource/${pkg}/${weight}.css`), "utf8");
  const block = css.split("/*").find((b) => b.includes(`${pkg}-latin-${weight}-normal */`));
  const range = block && /unicode-range:\s*([^;]+);/.exec(block);
  if (!range) throw new Error(`sync-design-system: no latin subset for @fontsource/${pkg} ${weight}`);
  return range[1].trim();
};
const fontFamilies = Object.entries(FONTS).map(([slug, f]) => ({
  name: f.family,
  slug,
  fontFamily: json.type.families[slug],
  fontFace: f.weights.map((weight) => {
    const file = `${f.pkg}-latin-${weight}-normal.woff2`;
    copyFileSync(resolve(root, `node_modules/@fontsource/${f.pkg}/files/${file}`), resolve(theme, "assets/fonts", file));
    return { fontFamily: f.family, fontStyle: "normal", fontWeight: String(weight), fontDisplay: "swap", src: [`file:./assets/fonts/${file}`], unicodeRange: latinRange(f.pkg, weight) };
  }),
}));

// Semantic colours only: components never use brand-* directly. Values stay `var(--token)`,
// so the Night theme ([data-theme="dark"]) re-colours everything the editor applies.
const PALETTE = ["paper", "mist", "ink", "ink-muted", "line", "line-strong", "band", "on-band", "on-band-muted", "accent", "on-accent", "accent-soft", "highlight", "on-highlight"];
const known = new Set(json.color.tokens.map((t) => t.name));
const title = (s) => s.split("-").map((w) => w[0].toUpperCase() + w.slice(1)).join(" ");
const palette = PALETTE.map((name) => {
  if (!known.has(name)) throw new Error(`sync-design-system: palette token ${name} missing from tokens.json`);
  return { name: title(name), slug: name, color: `var(--${name})` };
});

// Type: each style's usage note gives its responsive sizes, "(72 / 56 / 36)" or "(288 desktop · 160 tablet · 104 mobile)".
// Those become fluid min/max; single-size styles stay fixed.
const SIZES = ["display-hero", "display-xl", "h1", "h2", "h3", "h4", "h5", "h6", "quote", "lead", "body-lg", "body", "small", "caption", "button"];
const styles = Object.fromEntries(json.type.groups.flatMap((g) => g.styles).map((s) => [s.name, s]));
const fontSizes = SIZES.map((name) => {
  const s = styles[name];
  if (!s) throw new Error(`sync-design-system: type style ${name} missing from tokens.json`);
  const triple = /\((\d+)\D+(\d+)\D+(\d+)[^)]*\)/.exec(s.usage ?? "");
  const nums = triple ? triple.slice(1).map(Number) : [];
  const fluid = nums.length && Math.min(...nums) !== Math.max(...nums) ? { min: `${Math.min(...nums)}px`, max: `${Math.max(...nums)}px` } : false;
  return { name: title(name), slug: name, size: s.fontSize, fluid };
});
const bp = Object.fromEntries(json.breakpoint.tokens.map((t) => [t.name, t.value]));

const spacingSizes = json.spacing.tokens
  .filter((t) => t.name !== "space-0")
  .map((t) => ({ name: `${t.value} (${t.name})`, slug: t.name.replace(/^space-/, ""), size: `var(--${t.name})` }));
const layout = Object.fromEntries(json.layout.tokens.map((t) => [t.name, t.value]));

const base = JSON.parse(readFileSync(resolve(theme, "theme.base.json"), "utf8"));
delete base.$comment;
const themeJson = {
  $schema: base.$schema,
  version: base.version,
  settings: {
    ...base.settings,
    color: { ...base.settings.color, palette },
    layout: { contentSize: layout["container-text"], wideSize: layout["container-wide"] },
    spacing: { ...base.settings.spacing, spacingSizes },
    typography: { ...base.settings.typography, fluid: { minViewportWidth: "375px", maxViewportWidth: bp["bp-xl"] }, fontFamilies, fontSizes },
  },
  ...Object.fromEntries(Object.entries(base).filter(([k]) => !["$schema", "version", "settings"].includes(k))),
};
writeFileSync(
  resolve(theme, "theme.json"),
  JSON.stringify({ $comment: `GENERATED by scripts/sync-design-system.mjs from design-system/tokens.json (v${json.version}) + theme.base.json. Do not edit.`, ...themeJson }, null, 2) + "\n"
);

console.log("sync-design-system: wrote src/styles/ds/tokens.css, bundle.css, the plugin admin tokens.css and email theme.json, and the theme's css, fonts and theme.json");
